"""The CI/CD conformance suite: real jobs, generated by ``ci init``, run locally.

A CI/CD adapter's tests provide a ``ci_harness`` fixture, which runs one
generated job in the system's local runtime (``act`` for GitHub Actions), and
subclass :class:`CiConformance`. Each test gets a fresh :class:`World`: a
PostgreSQL source with a small shop database, stores, staging and copies
under a directory the Docker daemon can see, a cosign key pair, and a
repository holding the specs, their catalog lock and the jobs ``ci init``
wrote for both sides of the boundary. The jobs run the Datadouble image
named by ``DATADOUBLE_TEST_CI_IMAGE``.

Everything Datadouble writes belongs to the engine's user (999:999 for
PostgreSQL), so the world creates and removes its directories through a
container running as root.
"""

import json
import os
import secrets
import tempfile
import uuid
from collections.abc import Generator, Mapping
from contextlib import contextmanager
from dataclasses import dataclass, field
from enum import StrEnum
from pathlib import Path
from typing import Protocol
from unittest.mock import patch

import pytest
from pydantic import JsonValue

from datadouble import api
from datadouble.ci import JobKind, Side
from datadouble.names import Generation
from datadouble.programs import run_program
from datadouble.replicate import Copy

IMAGE_VARIABLE = "DATADOUBLE_TEST_CI_IMAGE"
WORK_VARIABLE = "DATADOUBLE_TEST_CI_WORK"
"""Where worlds live: a directory the Docker daemon can see (the system's temporary one)."""
POSTGRES = "postgres:18.4-trixie"
OWNER = "999:999"
"""The PostgreSQL image's user, which Datadouble runs as (decision 86)."""
RUNNERS = {Side.PRODUCTION: "prod-db", Side.NON_PRODUCTION: "staging"}

_SHOP = """
CREATE TABLE customer (id integer PRIMARY KEY, name text NOT NULL, email text NOT NULL);
CREATE TABLE orders (
    id integer PRIMARY KEY, customer_id integer NOT NULL REFERENCES customer, total numeric
);
INSERT INTO customer
    SELECT g, 'Customer ' || g, 'customer' || g || '@shop.example.com'
    FROM generate_series(1, 30) g;
INSERT INTO orders SELECT g, 1 + g % 30, g * 1.5 FROM generate_series(1, 90) g;
"""

_SPEC = """
name: shop
sources:
  app:
    engine: postgres
    connection:
      dsn:
        env: DDCI_SOURCE_DSN
runtime: {runtime}
strict:
  data: {strict}
subset:
  seeds:
    customer: "id <= 5"
  follow:
    down: [customer -> orders]
anonymize:
  customer:
    name:
      faker: name
    email:
      faker: email
      unique: true
verify:
  assertions:
    - name: no big customer numbers
      sql: "SELECT 1 FROM customer WHERE id > {limit}"
store:
  - filesystem:
      path: {base}/store
signing:
  cosign:
    key:
      env: DDCI_COSIGN_KEY
    transparency_log: false
trust:
  cosign:
    public_key:
      env: DDCI_COSIGN_PUB
    transparency_log: false
promote:
  to:
    - filesystem:
        path: {base}/export
fetch:
  from:
    filesystem:
      path: {base}/export
  staging: {base}/{mode}/staging
replicate:
  using:
    filesystem:
      path: {base}/{mode}/copies
  mode: {mode}
  size: {size}
notify:
  when: [failure, warning, recovery]
  to:
    - webhook:
        url:
          env: DDCI_WEBHOOK
"""
_HOOK = """
import http.server
import sys

class Hook(http.server.BaseHTTPRequestHandler):
    def do_POST(self):
        body = self.rfile.read(int(self.headers.get("Content-Length", "0")))
        if self.path != sys.argv[1]:
            self.send_response(404)
            self.end_headers()
            return
        print(body.decode(), flush=True)
        self.send_response(204)
        self.end_headers()

    def log_message(self, *args):
        pass

http.server.HTTPServer(("0.0.0.0", 8080), Hook).serve_forever()
"""
"""A webhook on the world's network that prints each body sent to its path on a line of its own.

The path names the world: a removed world's address can be given to the next
world's webhook, and a job of the earlier world still running must not reach it.
"""
UNREACHABLE = "http://127.0.0.1:9/hook"
"""A webhook nothing answers: notifying it fails."""


class Event(StrEnum):
    """What starts a job."""

    MANUAL = "manual"
    SCHEDULE = "schedule"
    REQUEST_OPENED = "request-opened"
    REQUEST_CLOSED = "request-closed"


class State(StrEnum):
    """A finished job's state, in the CI system's own terms mapped back."""

    SUCCESS = "success"
    WARNING = "warning"
    FAILURE = "failure"


@dataclass(frozen=True)
class JobRun:
    """A finished job."""

    state: State
    outputs: Mapping[str, str]
    log: str


@dataclass(frozen=True)
class RunContext:
    """What a job runs with."""

    secrets: Mapping[str, str]
    environ: Mapping[str, str]
    inputs: Mapping[str, str] = field(default_factory=dict[str, str])
    request: int | None = None
    run_id: str = "1"
    """The CI system's run: a run with the ID of an earlier one retries it."""


class CiHarness(Protocol):
    """One CI/CD system's local runtime."""

    @property
    def system(self) -> str:
        """The system's name in ``ci init``."""
        ...

    @property
    def hosted_runner(self) -> str | None:
        """A vendor's runner ``ci init`` must refuse, or None where there are none (Jenkins)."""
        ...

    @property
    def hosted_environment(self) -> Mapping[str, str]:
        """The environment of a vendor-hosted runner."""
        ...

    def prepare(self, repository: Path) -> None:
        """Make the generated jobs runnable locally, such as using this checkout's action."""
        ...

    def run(self, repository: Path, job: str, event: Event, context: RunContext) -> JobRun:
        """Run the generated job ``job`` (``build``, ``prune-production``...) and wait."""
        ...

    def uploaded(self) -> list[Path]:
        """Files jobs uploaded to the system's own artifact storage."""
        ...

    @property
    def artifact_storage(self) -> bool:
        """Whether the system keeps jobs' artifacts; without it (Argo CD) they go to the log."""
        ...

    def runtime(self, network: str, base: Path) -> Mapping[str, JsonValue]:
        """The container runtime jobs use, for a world on ``network`` with files in ``base``."""
        ...

    def runner(self, side: Side, base: Path) -> str:
        """Where one side's jobs run (a runner label, an agent label, a namespace)."""
        ...

    def owner(self, repository: Path, request: int) -> str:
        """Who a request's on-demand copies are for (``pr-7``, ``mr-1``)."""
        ...

    @property
    def init_fields(self) -> Mapping[str, str]:
        """More ``ci init`` fields for the system's jobs, such as ``agent`` and ``cloud``."""
        ...


def docker(*arguments: str, stdin: str | None = None, env: Mapping[str, str] | None = None) -> str:
    """Run a ``docker`` command and return its output; fail with its error."""
    done = run_program("docker", arguments, stdin=stdin, env=env)
    if done.status != 0:
        message = f"docker {arguments[0]} failed: {done.stderr.strip()}"
        raise RuntimeError(message)
    return done.stdout


@dataclass
class World:
    """A source, its stores and a repository with generated jobs."""

    name: str
    base: Path
    repository: Path
    image: str
    network: str
    secrets: dict[str, str]
    runtime: Mapping[str, JsonValue]
    """The spec's container runtime, as the harness's system runs jobs."""
    runners: Mapping[Side, str]

    @property
    def hook(self) -> str:
        """The container receiving the spec's webhook."""
        return f"{self.name}-hook"

    def notifications(self, job: str | None = None) -> list[dict[str, JsonValue]]:
        """The bodies the webhook was sent, oldest first; only ``job``'s, if given.

        A job that follows another in the same run (promote after build, in a
        GitLab pipeline or an Argo CD pod) notifies too, so tests pick the job.
        """
        lines = docker("logs", self.hook).splitlines()
        sent = [json.loads(line) for line in lines if line.startswith("{")]
        return [body for body in sent if job is None or body.get("job") == job]

    @property
    def store(self) -> Path:
        """The build's store."""
        return self.base / "store"

    def spec(self, mode: str) -> Path:
        """The spec for on-demand or pool copies."""
        return self.repository / "datadouble" / f"{mode}.yml"

    def write_spec(self, mode: str, *, limit: int = 1000, strict: str = "columns") -> Path:
        """Write a spec; ``limit`` below 5 fails verification, and ``strict`` is ``strict.data``."""
        path = self.spec(mode)
        size = 1 if mode == "on-demand" else 2
        text = _SPEC.format(
            base=self.base,
            runtime=json.dumps(self.runtime),
            mode=mode,
            size=size,
            limit=limit,
            strict=strict,
        )
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        return path

    def as_root(self, script: str) -> None:
        """Run a shell script over the world's directory (and its parent) as root."""
        root = self.base.parent
        docker(
            "run", "--rm", "--volume", f"{root}:{root}", "--entrypoint", "sh",
            "--user", "0:0", self.image, "-c", script,
        )  # fmt: skip

    def generations(self, under: Path) -> list[str]:
        """Image generations in a store or staging.

        A store holds ``<generation>.summary.json``; staging ``<generation>/summary.json``.
        """
        stored = {path.name.split(".")[0] for path in under.rglob("*.summary.json")}
        staged = {path.parent.name for path in under.rglob("summary.json")}
        return sorted(stored | staged)

    def copies(self, mode: str) -> tuple[Copy, ...]:
        """Copies ``replicate`` recorded, listed by ``copies`` as the engine's user."""
        spec = self.spec(mode)
        out = docker(
            "run", "--rm", "--user", OWNER,
            "--volume", f"{self.base}:{self.base}", "--volume", f"{spec.parent}:{spec.parent}",
            self.image, "--json", "copies", "--spec", str(spec),
        )  # fmt: skip
        response = api.CopiesResponse.model_validate_json(out)
        return response.result.copies

    def context(
        self,
        *,
        run_id: str = "1",
        request: int | None = None,
        inputs: Mapping[str, str] | None = None,
        environ: Mapping[str, str] | None = None,
        webhook: str | None = None,
    ) -> RunContext:
        """A run with the world's secrets, by default on a self-hosted runner marked inside.

        ``webhook`` replaces the URL the spec's ``notify`` posts to.
        """
        marked = {"DATADOUBLE_BOUNDARY": "inside", "RUNNER_ENVIRONMENT": "self-hosted"}
        chosen = self.secrets if webhook is None else {**self.secrets, "DDCI_WEBHOOK": webhook}
        return RunContext(
            secrets=chosen,
            environ=marked if environ is None else environ,
            inputs=inputs or {},
            request=request,
            run_id=run_id,
        )


@contextmanager
def world(harness: CiHarness, repository: Path) -> Generator[World]:
    """A fresh world: a source, directories, keys and generated jobs; removed afterwards."""
    image = os.environ[IMAGE_VARIABLE]
    name = f"ddci-{uuid.uuid4().hex[:10]}"
    root = Path(os.environ.get(WORK_VARIABLE, tempfile.gettempdir()))
    base = root / name
    network = name
    password = secrets.token_hex(16)
    docker("network", "create", network)
    try:
        docker(
            "run", "--detach", "--name", name, "--network", network,
            "--env", "POSTGRES_PASSWORD", POSTGRES,
            env={"POSTGRES_PASSWORD": password},
        )  # fmt: skip
        docker(
            "run", "--rm", "--volume", f"{root}:{root}", "--entrypoint", "sh",
            "--user", "0:0", image, "-c",
            f"install -d -m 0755 -o 999 -g 999 {base} {base}/store {base}/export {base}/work"
            f" {base}/on-demand/staging {base}/on-demand/copies {base}/pool/staging"
            f" {base}/pool/copies && install -d -m 0777 {base}/keys",
        )  # fmt: skip
        docker(
            "run", "--detach", "--name", f"{name}-hook", "--network", network,
            "--user", "65534:65534", "--entrypoint", "python", image, "-c", _HOOK,
            f"/hook/{name}",
        )  # fmt: skip
        runners = {side: harness.runner(side, base) for side in Side}
        built = World(
            name, base, repository, image, network, {}, harness.runtime(network, base), runners
        )
        try:
            _wait_for_source(name)
            address = docker(
                "inspect", "-f", f'{{{{(index .NetworkSettings.Networks "{network}").IPAddress}}}}',
                name,
            ).strip()  # fmt: skip
            built.secrets.update(_keys(built))
            built.secrets["DDCI_SOURCE_DSN"] = (
                f"postgresql://postgres:{password}@{address}:5432/postgres"
            )
            hook = docker(
                "inspect", "-f", f'{{{{(index .NetworkSettings.Networks "{network}").IPAddress}}}}',
                built.hook,
            ).strip()  # fmt: skip
            built.secrets["DDCI_WEBHOOK"] = f"http://{hook}:8080/hook/{name}"
            _generate(built, harness)
            yield built
        finally:
            built.as_root(f"rm -rf {base}")
    finally:
        docker("rm", "--force", "--volumes", name, f"{name}-hook")
        # A harness may have joined its own containers to the network, such as a
        # cluster's node; they leave it with the world.
        joined = docker(
            "network", "inspect", "--format", "{{range .Containers}}{{.Name}} {{end}}", network
        )
        for container in joined.split():
            docker("network", "disconnect", "--force", network, container)
        docker("network", "rm", network)


def _wait_for_source(name: str) -> None:
    # The server listens on TCP only once its first-start initialisation is done.
    docker(
        "exec", name, "timeout", "60", "sh", "-c",
        "until pg_isready --quiet --host 127.0.0.1 --username postgres; do sleep 1; done",
    )  # fmt: skip
    docker(
        "exec", "--interactive", name,
        "psql", "--username", "postgres", "--quiet", "--set", "ON_ERROR_STOP=1",
        stdin=_SHOP,
    )  # fmt: skip


def _keys(built: World) -> dict[str, str]:
    keys = built.base / "keys"
    password = secrets.token_hex(16)
    docker(
        "run", "--rm", "--volume", f"{keys}:{keys}", "--workdir", str(keys),
        "--user", f"{os.getuid()}:{os.getgid()}", "--env", "COSIGN_PASSWORD",
        "--entrypoint", "cosign", built.image, "generate-key-pair",
        env={"COSIGN_PASSWORD": password},
    )  # fmt: skip
    return {
        "DDCI_COSIGN_KEY": (keys / "cosign.key").read_text(encoding="utf-8"),
        "DDCI_COSIGN_PUB": (keys / "cosign.pub").read_text(encoding="utf-8"),
        "COSIGN_PASSWORD": password,
    }


def _history(repository: Path) -> tuple[str, str, str] | None:
    """The repository's HEAD, its number of commits and its uncommitted changes.

    None for a harness that keeps the jobs in no git repository (Argo CD reads
    them from the Application's values).
    """
    if not (repository / ".git").exists():
        return None

    def git(*arguments: str) -> str:
        done = run_program("git", ["-C", str(repository), *arguments])
        assert done.status == 0, done.stderr
        return done.stdout.strip()

    return (
        git("rev-parse", "HEAD"),
        git("rev-list", "--count", "HEAD"),
        git("status", "--porcelain"),
    )


def ci_init(built: World, system: str, spec: Path, *jobs: JobKind, **fields: str) -> api.Response:
    """Run ``ci init`` into the world's repository."""
    request = {
        "command": "ci.init",
        "system": system,
        "jobs": list(jobs),
        "spec": str(spec),
        "output": str(built.repository),
        "image": built.image,
        **fields,
    }
    return api.handle_json(json.dumps(request))


def _generate(built: World, harness: CiHarness) -> None:
    built.repository.mkdir(parents=True, exist_ok=True)
    on_demand = built.write_spec("on-demand")
    built.write_spec("pool")
    with patch.dict(os.environ, built.secrets):
        locked = api.handle_json(json.dumps({"command": "lock", "spec": str(on_demand)}))
    assert isinstance(locked, api.LockResponse), locked
    production = ci_init(
        built, harness.system, on_demand,
        JobKind.BUILD, JobKind.PROMOTE, JobKind.PRUNE, JobKind.LOCK,
        runner=built.runners[Side.PRODUCTION], work=str(built.base / "work"),
        **harness.init_fields,
    )  # fmt: skip
    assert isinstance(production, api.CiInitResponse), production
    assert set(production.environment) == set(built.secrets)
    others = (JobKind.FETCH, JobKind.PROVISION, JobKind.RELEASE, JobKind.PRUNE, JobKind.ACTIVATE)
    runner = built.runners[Side.NON_PRODUCTION]
    non_production = ci_init(
        built, harness.system, on_demand, *others, runner=runner, **harness.init_fields
    )
    assert isinstance(non_production, api.CiInitResponse), non_production
    assert "DDCI_SOURCE_DSN" not in non_production.environment
    assert "DDCI_WEBHOOK" in non_production.environment


class CiConformance:
    """The tests every CI/CD adapter must pass. Subclass with a ``ci_harness`` fixture."""

    @pytest.fixture
    def shop(self, ci_harness: CiHarness, tmp_path: Path) -> Generator[World]:
        """A fresh world, with the harness's local wiring in its repository."""
        with world(ci_harness, tmp_path / "repository") as built:
            ci_harness.prepare(built.repository)
            yield built

    def test_the_whole_on_demand_lifecycle(self, ci_harness: CiHarness, shop: World) -> None:
        """A build (failing, then retried) → promote → fetch → provision → release → rollback."""
        logs: list[str] = []

        def run(
            job: str,
            event: Event = Event.MANUAL,
            *,
            run_id: str = "1",
            request: int | None = None,
            inputs: Mapping[str, str] | None = None,
        ) -> JobRun:
            context = shop.context(run_id=run_id, request=request, inputs=inputs)
            done = ci_harness.run(shop.repository, job, event, context)
            logs.append(done.log)
            assert done.outputs.get("outcome") == done.state, done.log
            return done

        # A build that fails at its last stage resumes on retry, reusing what it did.
        shop.as_root(f"chmod 0555 {shop.store}")
        failed = run("build", run_id="101")
        assert failed.state is State.FAILURE
        shop.as_root(f"chmod 0755 {shop.store}")
        built = run("build", run_id="101")
        assert built.state is State.SUCCESS, built.log
        assert "extract: reused" in built.log
        first = Generation(built.outputs["generation"])
        assert failed.outputs["error"] == "store_failed"
        assert shop.generations(shop.store) == [first]

        assert run("promote").state is State.SUCCESS
        assert shop.generations(shop.base / "export") == [first]
        fetched = run("fetch")
        assert fetched.state is State.SUCCESS
        assert f"fetched {first}" in fetched.log
        assert f"skipped {first}" in run("fetch").log

        assert run("provision", Event.REQUEST_OPENED, request=7).state is State.SUCCESS
        (copy,) = shop.copies("on-demand")
        assert copy.owner == ci_harness.owner(shop.repository, 7)
        assert copy.generation == first
        assert run("release", Event.REQUEST_CLOSED, request=7).state is State.SUCCESS
        assert shop.copies("on-demand") == ()
        assert run("release", Event.SCHEDULE).state is State.SUCCESS

        second = Generation(run("build", run_id="102").outputs["generation"])
        assert second != first
        assert run("promote").state is State.SUCCESS
        assert f"fetched {second}" in run("fetch").log
        activated = run("activate", inputs={"generation": first})
        assert activated.state is State.SUCCESS
        assert f"now points at {first}" in activated.log
        run("provision", Event.REQUEST_OPENED, request=8)
        (copy,) = shop.copies("on-demand")
        assert copy.generation == first

        for side in ("production", "non-production"):
            assert run(f"prune-{side}").state is State.SUCCESS
        assert second in shop.generations(shop.base / "export")
        assert first in shop.generations(shop.base / "on-demand" / "staging")

        everything = "\n".join(logs)
        assert shop.secrets["DDCI_SOURCE_DSN"].split("@")[0].split(":")[-1] not in everything
        assert shop.secrets["COSIGN_PASSWORD"] not in everything
        assert shop.secrets["DDCI_COSIGN_KEY"].splitlines()[1] not in everything
        assert ci_harness.uploaded() == []

    def test_pool_mode(self, ci_harness: CiHarness, shop: World) -> None:
        """A pool fills from the active generation, with no requester."""
        pool_repository = shop.repository.parent / "pool-repository"
        (pool_repository / "datadouble").mkdir(parents=True)
        pool = pool_repository / "datadouble" / "pool.yml"
        pool.write_bytes(shop.spec("pool").read_bytes())
        made = ci_init(
            shop, ci_harness.system, pool, JobKind.FETCH, JobKind.PROVISION,
            runner=shop.runners[Side.NON_PRODUCTION], output=str(pool_repository),
            **ci_harness.init_fields,
        )  # fmt: skip
        assert isinstance(made, api.CiInitResponse), made
        ci_harness.prepare(pool_repository)
        context = shop.context(run_id="401")
        built = ci_harness.run(shop.repository, "build", Event.MANUAL, context)
        assert built.state is State.SUCCESS, built.log
        promoted = ci_harness.run(shop.repository, "promote", Event.MANUAL, context)
        assert promoted.state is State.SUCCESS, promoted.log
        fetched = ci_harness.run(pool_repository, "fetch", Event.SCHEDULE, context)
        assert fetched.state is State.SUCCESS, fetched.log
        provisioned = ci_harness.run(pool_repository, "provision", Event.SCHEDULE, context)
        assert provisioned.state is State.SUCCESS, provisioned.log
        copies = shop.copies("pool")
        assert len(copies) == 2
        assert all(copy.owner is None for copy in copies)

    def test_warnings_and_failures(self, ci_harness: CiHarness, shop: World) -> None:
        """A warning is the native warning state; a failed verification stores nothing.

        Both notify the spec's webhook, and a webhook that cannot be reached
        leaves the job's outcome alone.
        """
        spec = shop.spec("on-demand")
        spec.with_suffix(".lock").unlink()
        shop.write_spec("on-demand", strict="off")
        unheard = shop.context(run_id="200", webhook=UNREACHABLE)
        unreached = ci_harness.run(shop.repository, "build", Event.MANUAL, unheard)
        assert unreached.state is State.WARNING, unreached.log
        assert "a notification failed, webhook 1: the request failed" in unreached.log
        assert UNREACHABLE not in unreached.log
        assert shop.notifications("build") == []
        shop.as_root(f"rm -rf {shop.store}/shop && install -d -o 999 -g 999 {shop.store}")
        warned = ci_harness.run(shop.repository, "build", Event.MANUAL, shop.context(run_id="201"))
        assert warned.state is State.WARNING, warned.log
        assert warned.outputs["outcome"] == "warning"
        (warning,) = shop.notifications("build")
        assert warning["outcome"] == "warning"
        assert warning["generation"] == warned.outputs["generation"]
        shop.as_root(f"rm -rf {shop.store}/shop && install -d -o 999 -g 999 {shop.store}")
        shop.write_spec("on-demand", strict="off", limit=2)
        failed = ci_harness.run(shop.repository, "build", Event.MANUAL, shop.context(run_id="202"))
        assert failed.state is State.FAILURE, failed.log
        assert shop.generations(shop.store) == []
        refused = ci_harness.run(shop.repository, "promote", Event.MANUAL, shop.context())
        assert refused.state is State.FAILURE
        # A system may run a failed job again (a Kubernetes Job's backoffLimit).
        verifications = shop.notifications("build")[1:]
        assert verifications, shop.notifications()
        assert all(n["outcome"] == "failure" for n in verifications), verifications
        assert refused.outputs["error"] in {str(n["error"]) for n in shop.notifications("promote")}

    def test_a_failing_job_notifies(self, ci_harness: CiHarness, shop: World) -> None:
        """A failing job posts its outcome to the spec's webhook, never values or secrets.

        The first success after it posts one recovery, and later successes none.
        """
        shop.as_root(f"chmod 0555 {shop.store}")
        failed = ci_harness.run(shop.repository, "build", Event.MANUAL, shop.context(run_id="501"))
        assert failed.state is State.FAILURE, failed.log
        # A system may run a failed job again (a Kubernetes Job's backoffLimit);
        # each attempt is a run of its own and notifies.
        attempts = shop.notifications("build")
        assert attempts
        sent = attempts[0]
        assert all(attempt == sent for attempt in attempts), attempts
        assert set(sent) == {
            "spec", "job", "outcome", "recovered", "generation", "error", "run_url", "text",
        }  # fmt: skip
        assert sent["recovered"] is False
        assert sent["spec"] == "shop"
        assert sent["job"] == "build"
        assert sent["outcome"] == "failure"
        assert sent["error"] == "store_failed"
        assert sent["run_url"] is None or str(sent["run_url"]).startswith("http")
        assert str(sent["text"]).startswith("Datadouble shop: build failed (store_failed)")
        assert "\n" not in str(sent["text"])
        body = json.dumps(sent)
        for value in shop.secrets.values():
            assert value.splitlines()[0] not in body
        shop.as_root(f"chmod 0755 {shop.store}")
        built = ci_harness.run(shop.repository, "build", Event.MANUAL, shop.context(run_id="501"))
        assert built.state is State.SUCCESS, built.log
        # The first success after a failure recovers, once.
        (recovery,) = shop.notifications("build")[len(attempts) :]
        assert recovery["outcome"] == "success"
        assert recovery["recovered"] is True
        assert str(recovery["text"]).startswith("Datadouble shop: build recovered")
        again = ci_harness.run(shop.repository, "build", Event.MANUAL, shop.context(run_id="502"))
        assert again.state is State.SUCCESS, again.log
        assert shop.notifications("build") == [*attempts, recovery]

    def test_hosted_runners_are_refused(self, ci_harness: CiHarness, shop: World) -> None:
        """``build`` and ``lock`` are never generated for, nor run on, a vendor-hosted runner."""
        if ci_harness.hosted_runner is not None:
            for kind in (JobKind.BUILD, JobKind.LOCK):
                refused = ci_init(
                    shop, ci_harness.system, shop.spec("on-demand"), kind,
                    runner=ci_harness.hosted_runner, work=str(shop.base / "work"),
                    **ci_harness.init_fields,
                )  # fmt: skip
                assert isinstance(refused, api.ErrorResponse)
                assert refused.error is api.ErrorCode.CI_FAILED
        environ = {"DATADOUBLE_BOUNDARY": "inside", **ci_harness.hosted_environment}
        hosted = ci_harness.run(
            shop.repository, "build", Event.MANUAL, shop.context(run_id="301", environ=environ)
        )
        assert hosted.state is State.FAILURE, hosted.log
        assert hosted.outputs.get("error") == "outside_boundary", hosted.log
        unmarked = ci_harness.run(
            shop.repository, "build", Event.MANUAL,
            shop.context(run_id="302", environ={"RUNNER_ENVIRONMENT": "self-hosted"}),
        )  # fmt: skip
        assert unmarked.outputs.get("error") == "outside_boundary", unmarked.log
        assert shop.generations(shop.store) == []
        locked = ci_harness.run(
            shop.repository, "lock", Event.MANUAL, shop.context(run_id="303", environ=environ)
        )
        assert locked.state is State.FAILURE, locked.log
        assert locked.outputs.get("error") == "outside_boundary", locked.log

    def test_the_lock_job(self, ci_harness: CiHarness, shop: World) -> None:
        """``lock`` publishes the new lock and its changes for review, and commits nothing."""
        lock = shop.spec("on-demand").with_suffix(".lock")
        committed = lock.read_bytes()
        history = _history(shop.repository)
        docker(
            "exec", shop.name, "psql", "--username", "postgres", "--quiet",
            "--set", "ON_ERROR_STOP=1", "--command", "ALTER TABLE customer ADD COLUMN phone text",
        )  # fmt: skip
        done = ci_harness.run(shop.repository, "lock", Event.MANUAL, shop.context(run_id="501"))
        assert done.state is State.SUCCESS, done.log
        assert done.outputs.get("changes") == "1", done.log
        assert "added column postgres.public.customer.phone: text (text) null" in done.log
        assert lock.read_bytes() == committed
        assert _history(shop.repository) == history
        if ci_harness.artifact_storage:
            names = {path.name for path in ci_harness.uploaded()}
            assert {"on-demand.lock", "changes.txt"} <= names, names
        else:
            assert "==> datadouble-lock/on-demand.lock <==" in done.log
            assert '"name": "phone"' in done.log
        assert shop.secrets["DDCI_SOURCE_DSN"].split("@")[0].split(":")[-1] not in done.log
